package com.bank.annot;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class TransferAnnotationsDemo {
    private static final Logger log = Logger.getLogger(TransferAnnotationsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000.00"));

        // @FunctionalInterface target used as a lambda.
        TransferValidator positive = (from, amount) -> amount.signum() > 0;
        BalanceValidator balance = new BalanceValidator();

        TransferService service = new TransferService();
        var amount = new BigDecimal("45000.00");

        if (positive.validate(rajesh, amount) && balance.validate(rajesh, amount)) {
            service.transfer(rajesh, priya, amount);   // new API
            log.info(() -> "Rajesh=" + rajesh.getBalance() + ", Priya=" + priya.getBalance());
        }

        // Deprecated method still works but warns callers to migrate.
        service.transferLegacy(rajesh, priya, new BigDecimal("1000.00"));

        // @SafeVarargs helper builds a list from generic varargs.
        List<BigDecimal> fees = TransferService.listOf(
                new BigDecimal("50.00"), new BigDecimal("18.00"));
        log.info(() -> "fees = " + fees);
    }
}

