class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;

    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal amt) { this.balance = this.balance.subtract(amt); }
    void credit(BigDecimal amt) { this.balance = this.balance.add(amt); }
}

// ─── Would be in validate/TransferValidator.java in a real project ───
@FunctionalInterface
interface TransferValidator {
    boolean validate(Account from, BigDecimal amount);   // exactly ONE abstract method
    // Adding a second abstract method here would be a COMPILE ERROR.
    default TransferValidator and(TransferValidator other) {
        return (f, a) -> this.validate(f, a) && other.validate(f, a);  // default is allowed
    }
}

// ─── Would be in validate/BaseValidator.java in a real project ───
class BaseValidator {
    boolean validate(Account from, BigDecimal amount) {
        return from != null && amount != null;
    }
}

// ─── Would be in validate/BalanceValidator.java in a real project ───
class BalanceValidator extends BaseValidator {
    // @Override verifies this truly overrides BaseValidator.validate.
    @Override
    boolean validate(Account from, BigDecimal amount) {
        return super.validate(from, amount)
                && from.getBalance().compareTo(amount) >= 0;
    }
}

// ─── Would be in service/TransferService.java in a real project ───
class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());

    // New, preferred API.
    void transfer(Account from, Account to, BigDecimal amount) {
        from.debit(amount);
        to.credit(amount);
        log.info(() -> "transfer " + amount + " " + from.getAccountId()
                + " -> " + to.getAccountId());
    }

    // Old API kept for compatibility, scheduled for removal.
    @Deprecated(since = "2.1", forRemoval = true)
    void transferLegacy(Account from, Account to, BigDecimal amount) {
        log.warning("transferLegacy is deprecated; use transfer(...)");
        transfer(from, to, amount);
    }

    // Narrowly scoped suppression with justification.
    @SuppressWarnings("unchecked")
    static <T> T castLegacy(Object legacy) {
        // Legacy raw integration returns Object; cast is verified safe by contract.
        return (T) legacy;
    }

    // @SafeVarargs: method only READS the varargs; no heap pollution.
    @SafeVarargs
    static <T> List<T> listOf(T... items) {
        return List.of(items);
    }
}

// ─── Would be in util/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
